{
  "steps": [
    {
      "task": "Detect and extract spatial and temporal coverage from the dataset",
      "player": "spatial_temporal_specialist",
      "rationale": "The iNaturalist Croissant standard requires only spatialCoverage and temporalCoverage. This step uses mandatory detection tools (detect_spatial_columns, detect_temporal_columns) and extent tools to extract the geographic bounding box and time range from the data.",
      "target_resources": [],
      "inputs": {},
      "outputs": [
        "spatial_temporal_data"
      ]
    },
    {
      "task": "Generate iNaturalist Croissant metadata JSON with spatial and temporal coverage",
      "player": "croissant_inaturalist_metadata_generator",
      "rationale": "Final step to produce the required metadata output. It consumes the spatial_temporal artifact to populate spatialCoverage and temporalCoverage fields as required by the iNaturalist Croissant standard.",
      "target_resources": [],
      "inputs": {
        "metadata_standard": "metadata_standard",
        "spatial_temporal": "spatial_temporal_data"
      },
      "outputs": [
        "metadata_output"
      ]
    }
  ]
}

resolved_inputs.metadata_standard:
{
    "spatialCoverage": "Geographic bounding box in WGS84 with numeric fields: min_lat, min_lon, max_lat, max_lon",
    "temporalCoverage": "Time period covered with ISO 8601 date or datetime strings: from, to"
}

